using Elevant.Application.Abstractions.Commercial;

namespace Elevant.Infrastructure.Integrations.AirlineRegistry;

/// <summary>
/// Offline airline registry from OpenFlights (ODbL 1.0), embedded at build time and generated by
/// <c>scripts/data/generate-openflights-airlines.mjs</c>. It answers when Wikidata cannot; its
/// data is older, so the source is always shown with the result (ADR-0023).
/// </summary>
public sealed class OpenFlightsAirlineRegistrySource : IAirlineRegistrySource
{
    private static readonly Lazy<IReadOnlyList<AirlineRegistryCandidate>> Rows = new(Load);

    public string Name => "OpenFlights";

    public int Order => 20;

    public Task<IReadOnlyList<AirlineRegistryCandidate>?> FindAsync(string? iataCode, string? icaoCode,
        CancellationToken cancellationToken = default)
    {
        var iata = iataCode?.Trim().ToUpperInvariant();
        var icao = icaoCode?.Trim().ToUpperInvariant();
        IReadOnlyList<AirlineRegistryCandidate> matches = Rows.Value.Where(row =>
            !string.IsNullOrEmpty(iata) && row.IataCodes.Contains(iata) ||
            !string.IsNullOrEmpty(icao) && row.IcaoCodes.Contains(icao)).ToArray();
        return Task.FromResult<IReadOnlyList<AirlineRegistryCandidate>?>(matches);
    }

    private static IReadOnlyList<AirlineRegistryCandidate> Load()
    {
        var text = System.Text.Encoding.UTF8.GetString(EmbeddedResources.Read("openflights-airlines.tsv"));
        var rows = new List<AirlineRegistryCandidate>();
        foreach (var line in text.Split('\n'))
        {
            if (line.Length == 0 || line[0] == '#' || line.StartsWith("name\t", StringComparison.Ordinal)) continue;
            var fields = line.TrimEnd('\r').Split('\t');
            if (fields.Length != 5) continue;
            rows.Add(new AirlineRegistryCandidate(fields[0],
                fields[1].Length == 0 ? [] : [fields[1]], fields[2].Length == 0 ? [] : [fields[2]],
                fields[3].Length == 0 ? null : fields[3], fields[4] == "Y", null));
        }
        return rows;
    }
}
